  --color-blue-600: #1868db;
  --color-blue-700: #1a59d9;
  --color-indigo-50: #eef2ff;
  --color-indigo-600: #4f46e5;
  --color-orange-100: #ffedd5;
  --color-orange-600: #ea580c;
}

@layer base {
  * {
    box-sizing: border-box;
  }

  body {
    margin: 0;
    font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
}

@layer utilities {
  .btn-primary {
    @apply px-4 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-lg transition-colors;
  }

  .section-padding {
    @apply py-16 md:py-24;
  }
}

/* Cookie banner animation */
@keyframes slideUp {
  from {
    transform: translateY(100%);
    opacity: 0;
  }
  to {
    transform: translateY(0);
    opacity: 1;
  }
}

.cookie-banner {
  animation: slideUp 0.3s ease-out;
}

/* Smooth scroll */
html {
  scroll-behavior: smooth;
}

/* Focus styles */
:focus-visible {
  outline: 2px solid #1868db;
  outline-offset: 2px;
}

/* Modal backdrop blur */
.modal-backdrop {
  backdrop-filter: blur(4px);
}

/* Gradient text */
.gradient-text {
  background: linear-gradient(to right, #1868db, #4f46e5);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

/* Custom range slider */
input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  height: 8px;
  background: #e5e7eb;
  border-radius: 4px;
  outline: none;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 20px;
  height: 20px;
  background: #1868db;
  border-radius: 50%;
  cursor: pointer;
}

input[type="range"]::-moz-range-thumb {
  width: 20px;
  height: 20px;
  background: #1868db;
  border-radius: 50%;
  cursor: pointer;
  border: none;
}

/* Table styles */
table {
  border-collapse: collapse;
}

th, td {
  border: 1px solid #e5e7eb;
}

th {
  background-color: #f9fafb;
}

